        ),
        "parameters": {
            "type": "object",
            "properties": {
                "kind": {
                    "type": "string",
                    "enum": sorted(OBSERVATION_KINDS),
                    "description": "The area of context this observation belongs to.",
                },
                "text": {
                    "type": "string",
                    "description": "One plain-language sentence in the PM's own terms.",
                },
                "confidence": {
                    "type": "number",
                    "minimum": 0,
                    "maximum": 1,
                    "description": "How sure you are. Defaults to 0.6.",
                },
